#!/usr/bin/env node
// Save the YAML generated by the Tier Profile window to the project config.
// Usage:
//   node <skill-dir>/scripts/save-tier-profile.mjs [--project <dir>] < tiers.yaml
// The file is always written to <project>/.t3-orca/tiers.yaml.

import { existsSync, mkdirSync, readFileSync, realpathSync, renameSync, rmSync, statSync, writeFileSync } from "node:fs";
import { dirname, isAbsolute, join, relative, resolve, sep } from "node:path";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const USAGE =
  "Usage: node <skill-dir>/scripts/save-tier-profile.mjs [--project <dir>] < tiers.yaml";
const MAX_PROFILE_BYTES = 64 * 1024;

export function resolveProjectRoot(cwd = process.cwd()) {
  try {
    const root = execFileSync("git", ["rev-parse", "--show-toplevel"], {
      cwd,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
    if (root) return realpathSync(root);
  } catch {
    // Fall through to the current directory.
  }
  return realpathSync(cwd);
}

export function validateProfileText(text) {
  const value = String(text == null ? "" : text).replace(/^\uFEFF/, "");
  if (!value.trim()) throw new Error("Profile input is empty.");
  if (Buffer.byteLength(value, "utf8") > MAX_PROFILE_BYTES) {
    throw new Error(`Profile input is larger than ${MAX_PROFILE_BYTES} bytes.`);
  }
  if (value.includes("\0")) throw new Error("Profile input contains NUL bytes.");
  if (!/^tiers\s*:/m.test(value)) {
    throw new Error('Profile input must contain a top-level "tiers:" block.');
  }
  return value.endsWith("\n") ? value : value + "\n";
}

function isWithin(root, target) {
  const rel = relative(root, target);
  return rel === "" || (!rel.startsWith(".." + sep) && rel !== ".." && !isAbsolute(rel));
}

export function resolveTierProfileTarget({ project, cwd = process.cwd() }) {
  const requestedRoot = project ? resolve(cwd, project) : resolveProjectRoot(cwd);
  if (!existsSync(requestedRoot) || !statSync(requestedRoot).isDirectory()) {
    throw new Error(`Project directory does not exist: ${requestedRoot}`);
  }
  const projectRoot = realpathSync(requestedRoot);

  const profileDir = join(projectRoot, ".t3-orca");
  mkdirSync(profileDir, { recursive: true });
  const resolvedDir = realpathSync(profileDir);
  if (!isWithin(projectRoot, resolvedDir)) {
    throw new Error(`Refusing to write outside the project: ${resolvedDir}`);
  }

  return join(resolvedDir, "tiers.yaml");
}

export function saveTierProfile({ project, text, cwd = process.cwd() }) {
  const target = resolveTierProfileTarget({ project, cwd });
  const content = validateProfileText(text);
  const temp = join(dirname(target), `.tiers.yaml.tmp-${process.pid}-${Date.now()}`);
  try {
    writeFileSync(temp, content, "utf8");
    try {
      renameSync(temp, target);
    } catch {
      rmSync(target, { force: true });
      renameSync(temp, target);
    }
  } finally {
    rmSync(temp, { force: true });
  }
  return target;
}

export function runCli(argv = process.argv.slice(2), { stdinText } = {}) {
  if (argv.includes("-h") || argv.includes("--help")) {
    console.log(USAGE);
    return 0;
  }

  let project;
  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    if (arg === "--project") {
      project = argv[index + 1];
      if (!project) {
        console.error("--project requires a directory.");
        console.error(USAGE);
        return 2;
      }
      index += 1;
    } else if (arg.startsWith("--project=")) {
      project = arg.slice("--project=".length);
      if (!project) {
        console.error("--project requires a directory.");
        console.error(USAGE);
        return 2;
      }
    } else {
      console.error(`Unknown argument: ${arg}`);
      console.error(USAGE);
      return 2;
    }
  }

  try {
    const text = typeof stdinText === "string" ? stdinText : readFileSync(0, "utf8");
    const target = saveTierProfile({ project, text });
    console.log(target);
    return 0;
  } catch (error) {
    console.error(error.message);
    return 1;
  }
}

function isMainModule() {
  if (!process.argv[1]) return false;
  try {
    return realpathSync(fileURLToPath(import.meta.url)) === realpathSync(resolve(process.argv[1]));
  } catch {
    return false;
  }
}

if (isMainModule()) {
  process.exitCode = runCli();
}
